def _fold(text: str) -> str:
    """Lower-case, accent-stripped key for tolerant location matching."""
    import unicodedata
    return "".join(
        c for c in unicodedata.normalize("NFKD", str(text or "").strip().lower())
        if not unicodedata.combining(c)
    )


_FOLDED_LOCATIONS = {_fold(k): v for k, v in LOCATION_TO_CIRCUIT.items()}


def resolve_circuit_key(location: str) -> str | None:
    """Map a fastf1 `Location` to a key in CIRCUITS, or None if we have no
    circuit record for it.

    Returning None matters: the old code fell back to a slugified location,
    which is always truthy, so the UI rendered "View full page" links to
    circuits that don't exist (Madrid, Kuala Lumpur) and 404'd.
    """
    if not location:
        return None
    folded = _fold(location)
    key = _FOLDED_LOCATIONS.get(folded)
    if key:
        return key
    slug = folded.replace(" ", "_").replace("-", "_")
    return slug if slug in CIRCUITS else None
